entries.content:
每次当用户要求生成或更新状态栏时，你必须严格遵循以下格式输出【源文件】部分，不要添加任何解释或无关内容，不可以输出未知要有详细描述。

[HUD_START]
config:
  theme: retro_succubus
  layout: vertical

[time_date_location]
current_time: {{当前时间}}
current_date: {{当前日期}}
current_location: {{当前地点}}

[protagonist_list]
name: {{主角名字}}
height: {{主角身高}}
weight: {{主角体重}}
bust: {{胸围}}
waist: {{腰围}}
hips: {{臀围}}
age: {{年龄}}
posture: {{身体姿势}}
expression: {{面部表情}}
tail_state: {{尾巴状态}}
clothing: {{衣服着装}}
appearance: {{人物外观}}
internal_state: {{内部状态}}
orgasm_value: {{高潮值}}
pain_value: {{疼痛值}}
fatigue_value: {{疲劳值}}
hunger_value: {{饥饿值}}
urination_value: {{排尿值}}

[npc_list]
npc_name: {{NPC名称}}
appearance: {{外观特征}}
height: {{身高}}
weight: {{体重}}
appearance_detail: {{人物外观}}
internal_state: {{内部状态}}
orgasm_value: {{高潮射精值}}
pain_value: {{疼痛值}}

[map_movement_list]
location_1: {{地点1}}
movement_time_1: {{移动时间1}}
location_2: {{地点2}}
movement_time_2: {{移动时间2}}
location_3: {{地点3}}
movement_time_3: {{移动时间3}}
[HUD_END]

